package vn.edu.hcmute.bookstore_24110202.controller; import jakarta.servlet.annotation.*; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.*; import java.security.*; import vn.edu.hcmute.bookstore_24110202.dto.*; import vn.edu.hcmute.bookstore_24110202.service.impl.*;
@WebServlet("/register") public class RegisterController_24110202 extends HttpServlet {private final UserServiceImpl_24110202 users=new UserServiceImpl_24110202();private final EmailServiceImpl_24110202 mail=new EmailServiceImpl_24110202();protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{q.getRequestDispatcher("/WEB-INF/views/auth/register.jsp").include(q,p);}protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{RegisterForm_24110202 f=new RegisterForm_24110202();f.setEmail(q.getParameter("email"));f.setFullname(q.getParameter("fullname"));f.setPhone(q.getParameter("phone"));f.setPassword(q.getParameter("password"));f.setConfirmPassword(q.getParameter("confirmPassword"));var result=users.validateRegister(f);if(!result.isValid()){q.setAttribute("errors",result.getFieldErrors());q.setAttribute("message",result.getGlobalError());doGet(q,p);return;}String otp=String.format("%06d",new SecureRandom().nextInt(1000000));try{mail.sendOtp(f.getEmail(),otp);}catch(RuntimeException e){q.setAttribute("message","Không gửi được email OTP. Vui lòng thử lại.");doGet(q,p);return;}HttpSession s=q.getSession(true);s.setAttribute("pendingRegisterForm",f);s.setAttribute("registerOtp",otp);s.setAttribute("otpExpiresAt",System.currentTimeMillis()+300000L);s.setAttribute("otpAttempts",0);p.sendRedirect(q.getContextPath()+"/verify-otp");}}
